-- PILI-AIRE — 2026 feed data from "PILI_feed_data.xlsx". Run ONCE in the Supabase SQL editor, AFTER Build 86
-- (sales agents) is pushed. One transaction: any error loads nothing. Running it twice is refused.
--
-- 1. AGENTS: 9 freelance agents (Bro. Jr, Bro. Manuel, Bro. Mel, Bro. Rhoge, Bro. Rocky, Bro. Roxie, Bro. Vin, Ptr. Rod, Sis. Jackie); existing agents with the same name are reused.
-- 2. CUSTOMERS: the Client List (192) — matched by code, then by name; missing ones created with their CUS-PILI code;
--    each gets its Assigned Agent. 2 customers only in the Sales Record are created too.
-- 3. SALES: 2153 DRs, Jan 2 – Oct 1 2026, total 6,899,046.05, cost (Total Cost) 4,151,287.65. Each DR = one completed,
--    fully paid Storefront sale (paper DR no. in Hardcopy DR, app DR PILI-DR-<no>), no item lines, no stock movement,
--    with the agent written on the DR (blank = Store). The agent commission per DR (266,326.11 in all) is kept in the notes
--    for the commission build. One history day-closing + posted journal per month:
--      Dr 1090 Clearing / Cr 4000 Sales   and   Dr 5000 Cost of sales / Cr 1090 Clearing.
-- 4. EXPENSES: Expense List Jan–Sep, 204 entries, 1,395,201.39 (annual items 13th month, business permit,
--    giveaways at 1/12 a month), Admin department, paid, each with a posted journal Dr expense account / Cr 1090 Clearing.
begin;
do $$
declare
  b uuid; v_loc uuid; v_fin uuid; v_admin uuid; v_walk uuid; r record; v_id uuid; v_n int; v_mon int; v_close uuid; v_je uuid; v_cdate date;
  v_tot numeric; v_cost numeric; v_cnt int; v_cat uuid; v_month uuid; v_exp uuid; v_date date; v_label text; v_e int := 0; v_s int := 0; v_skip int := 0;
begin
  select id into b from public.businesses where code = 'PILI';
  if b is null then raise exception 'Business PILI not found.'; end if;
  if to_regclass('public.sales_agents') is null then raise exception 'Push Build 86 (sales agents) first.'; end if;
  if exists (select 1 from public.storefront_sales where business_id = b and notes like 'Loaded from PILI feed%')
     or exists (select 1 from public.expenses where business_id = b and notes = 'Loaded from PILI feed') then
    raise exception 'The PILI feed data was already loaded.';
  end if;
  select location_id, walk_in_customer_id into v_loc, v_walk from public.storefront_settings where business_id = b;
  if v_loc is null then select id into v_loc from public.logistics_locations where business_id = b and active order by created_at limit 1; end if;
  if v_loc is null then raise exception 'PILI has no stock location; set one in Storefront settings first.'; end if;
  if v_walk is null then
    select id into v_walk from public.finance_customers where business_id = b and lower(legal_name) in ('walk-in customer','walk in','walk-in') limit 1;
  end if;
  if v_walk is null then raise exception 'PILI has no walk-in customer; open the Storefront once (it creates it) and run this again.'; end if;
  select id into v_fin from public.sections where code = 'finance';
  select id into v_admin from public.sections where code = 'admin';

  -- 1. agents
  create temp table _ag(name text, id uuid) on commit drop;
  insert into _ag(name) values ('Bro. Jr'), ('Bro. Manuel'), ('Bro. Mel'), ('Bro. Rhoge'), ('Bro. Rocky'), ('Bro. Roxie'), ('Bro. Vin'), ('Ptr. Rod'), ('Sis. Jackie');
  for r in select * from _ag loop
    select id into v_id from public.sales_agents where kind = 'freelance' and lower(btrim(name)) = lower(r.name) limit 1;
    if v_id is null then
      select coalesce(max(substring(agent_code from 4)::int), 0) + 1 into v_n from public.sales_agents where agent_code ~ '^AG-[0-9]+$';
      insert into public.sales_agents(agent_code, name, kind, notes) values ('AG-' || lpad(v_n::text, 4, '0'), r.name, 'freelance', 'Created from PILI feed data')
      returning id into v_id;
    end if;
    update _ag set id = v_id where name = r.name;
  end loop;
  insert into _ag values ('Store', public.sales_agent_store(b));

