  for v_mon in select distinct extract(month from d)::int from _s order by 1 loop
    select coalesce(sum(total), 0), coalesce(sum(cost), 0), count(*), max(d) into v_tot, v_cost, v_cnt, v_cdate from _s where extract(month from d) = v_mon;
    v_cdate := greatest(v_cdate, least((make_date(2026, v_mon, 1) + interval '1 month' - interval '1 day')::date, (now() at time zone 'Asia/Manila')::date - 1));
    while exists (select 1 from public.storefront_closings where business_id = b and closing_date = v_cdate and status <> 'returned') loop v_cdate := v_cdate - 1; end loop;
    insert into public.finance_journal_entries(business_id, journal_number, entry_date, description, source_module, section_id, status, total_debit, total_credit, posted_at, notes)
    values (b, 'PILI-SLH-2026-' || lpad(v_mon::text, 2, '0'), v_cdate, 'Sales history (loaded): ' || to_char(make_date(2026, v_mon, 1), 'FMMonth YYYY'), 'storefront', v_fin, 'posted',
            v_tot + v_cost, v_tot + v_cost, now(), 'Loaded from PILI feed')
    returning id into v_je;
    insert into public.finance_journal_lines(business_id, journal_entry_id, account_id, line_description, debit, credit, department) values
      (b, v_je, public.sf_gl(b, '1090'), 'Sales before the app — to reclassify', v_tot, 0, 'Sales'),
      (b, v_je, public.sf_gl(b, '4000'), 'Sales ' || to_char(make_date(2026, v_mon, 1), 'FMMonth YYYY') || ' (' || v_cnt || ' DRs)', 0, v_tot, 'Sales');
    if v_cost > 0 then
      insert into public.finance_journal_lines(business_id, journal_entry_id, account_id, line_description, debit, credit, department) values
        (b, v_je, public.sf_gl(b, '5000'), 'Cost of sales ' || to_char(make_date(2026, v_mon, 1), 'FMMonth YYYY'), v_cost, 0, 'Sales'),
        (b, v_je, public.sf_gl(b, '1090'), 'Cost of goods sold before the app — to reclassify', 0, v_cost, 'Sales');
    end if;
    insert into public.storefront_closings(business_id, closing_number, closing_date, status, sales_count, sales_total, returns_total, charged_to_ar, ar_collected,
                                           expected_cash, counted_cash, variance, notes, submitted_at, decided_at, decision_note, journal_entry_id, posted_at)
    values (b, 'PILI-CLH-2026-' || lpad(v_mon::text, 2, '0'), v_cdate, 'approved', v_cnt, v_tot, 0, 0, 0, 0, 0, 0,
            'Sales history ' || to_char(make_date(2026, v_mon, 1), 'FMMonth YYYY') || ' — loaded from PILI feed data (not a cash count)', now(), now(), 'Loaded history', v_je, now())
    returning id into v_close;
    update public.finance_journal_entries set source_record_id = v_close where id = v_je;
    for r in select * from _s where extract(month from d) = v_mon order by d, dr loop
      if exists (select 1 from public.storefront_sales where business_id = b and status <> 'cancelled' and hardcopy_dr_no is not null
                  and public.sf_hardcopy_key(hardcopy_dr_no) = public.sf_hardcopy_key(r.dr)) then
        v_skip := v_skip + 1; raise notice 'DR % is already in the app — skipped.', r.dr; continue;
      end if;
      insert into public.storefront_sales(business_id, sale_number, sale_date, status, customer_id, location_id, issue_dr, dr_number, hardcopy_dr_no,
                                          subtotal, discount_total, total, amount_paid, balance, cost_total, notes, completed_at, approved_at,
                                          closing_id, late_entry, late_reason, release_status, released_at, vat_applied, vat_amount, agent_id)
      values (b, 'PILI-SH-2026-' || r.dr, r.d, 'completed', case when r.cust = 'WALKIN' then v_walk else (select id from _c where name = r.cust) end, v_loc, true,
              'PILI-DR-' || r.dr, r.dr, r.total, 0, r.total, r.total, 0, r.cost,
              'Loaded from PILI feed · agent ' || r.agent || case when r.comm > 0 then ' · commission ' || to_char(r.comm, 'FM999,999,990.00') else '' end
                || ' · ' || r.lines || ' line(s)' || case when r.sheet_cust <> r.cust and r.cust <> 'WALKIN' then ' · client as written: ' || r.sheet_cust else '' end,
              r.d::timestamp + interval '12 hours', r.d::timestamp + interval '12 hours', v_close, true, 'Sales history loaded from the PILI feed data',
              'released', r.d::timestamp + interval '12 hours', false, 0, (select id from _ag where name = r.agent));
      v_s := v_s + 1;
    end loop;
  end loop;
  perform set_config('ibx.agent_override', 'off', true);

