    ('Give away / Calendar', 'Marketing & Giveaways', '5200', 7, 1000.0),
    ('Give away / Calendar', 'Marketing & Giveaways', '5200', 8, 1000.0),
    ('Give away / Calendar', 'Marketing & Giveaways', '5200', 9, 1000.0);
  for r in select * from _e order by mon, cat, item loop
    select id into v_cat from public.admin_expense_categories where lower(name) = lower(r.cat) limit 1;
    if v_cat is null then
      insert into public.admin_expense_categories(code, name, gl_account_code, active)
      values (trim(both '_' from lower(regexp_replace(r.cat, '[^a-zA-Z0-9]+', '_', 'g'))), r.cat, r.gl, true)
      on conflict (code) do update set name = excluded.name
      returning id into v_cat;
    end if;
    v_date := (make_date(2026, r.mon, 1) + interval '1 month' - interval '1 day')::date;
    v_label := to_char(make_date(2026, r.mon, 1), 'FMMonth YYYY');
    insert into public.months(business_id, year, month, label) values (b, 2026, r.mon, v_label) on conflict do nothing;
    select id into v_month from public.months where business_id = b and year = 2026 and month = r.mon;
    insert into public.expenses(business_id, section_id, month_id, description, amount, status, expense_date, category_id, notes, posted_at, paid_at)
    values (b, v_admin, v_month, btrim(r.item) || ' — ' || v_label, r.amount, 'paid', v_date, v_cat, 'Loaded from PILI feed', now(), now())
    returning id into v_exp;
    v_e := v_e + 1;
    insert into public.finance_journal_entries(business_id, journal_number, entry_date, description, source_module, source_record_id, section_id, status,
                                               total_debit, total_credit, posted_at, notes)
    values (b, 'PILI-EXH-2026-' || lpad(v_e::text, 6, '0'), v_date, 'Expense (loaded): ' || btrim(r.item) || ' — ' || v_label, 'expenses', v_exp,
            v_fin, 'posted', r.amount, r.amount, now(), 'Loaded from PILI feed')
    returning id into v_je;
    insert into public.finance_journal_lines(business_id, journal_entry_id, account_id, line_description, debit, credit, department) values
      (b, v_je, public.sf_gl(b, coalesce((select nullif(gl_account_code, '') from public.admin_expense_categories where id = v_cat), r.gl)), btrim(r.item) || ' — ' || v_label, r.amount, 0, 'Admin'),
      (b, v_je, public.sf_gl(b, '1090'), 'Paid before the app — to reclassify', 0, r.amount, 'Admin');
    update public.expenses set journal_entry_id = v_je where id = v_exp;
  end loop;

  raise notice 'Loaded % sales (% skipped as already in the app), % expenses; % agents, % customers checked.', v_s, v_skip, v_e, (select count(*) from _ag) - 1, (select count(*) from _c);
end $$;
commit;
